//! 🌊️ Handcrafted persisted Flow parent and exact composed child handle.
use super::FlowSnapshot;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,Reconstruction,NativeEncodingBound}}};
impl ArtifactSqliteSnapshot for FlowSnapshot{
 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{c.check_rows(2)?;store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),Self::__dsl_from_record_controlled,c)}
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,String>{c.check_rows(2)?;store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),c)}
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;let target=&self.content.target;let dialect=&target.dialect;p.insert("flow_document",&[Cell::Text(&self.schema)])?;p.insert("flow_content",&[Cell::Text(&self.content.child_id),Cell::Text(&target.artifact_id),Cell::Text(&dialect.artifact_kind),Cell::Text(&dialect.standard),Cell::Text(&dialect.subset)])?;p.finish()}
 fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits()).map_err(|e|e.to_string())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let document=d.table("flow_document")?.single_row()?;let content=d.table("flow_content")?.single_row()?;if document.rowid!=1||content.rowid!=1||document.integer(0)?!=1||content.integer(0)?!=1||document.values.len()!=2||content.values.len()!=6{return Err("Flow requires exact identity-1 parent and child rows".into())}let mut r=Reconstruction::new(c)?;let schema=r.text(document.text(1)?)?;let child_id=r.text(content.text(1)?)?;let artifact_id=r.text(content.text(2)?)?;let artifact_kind=r.text(content.text(3)?)?;let standard=r.text(content.text(4)?)?;let subset=r.text(content.text(5)?)?;r.checkpoint()?;Ok(Self{schema,content:store::ArtifactChild::new(child_id,store::os_io::ArtifactRef{artifact_id,dialect:store::os_io::ArtifactDialect{artifact_kind,standard,subset}})})}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=NativeEncodingBound::new(c)?;b.add(4096)?;let target=&self.content.target;let dialect=&target.dialect;for text in[&self.schema,&self.content.child_id,&target.artifact_id,&dialect.artifact_kind,&dialect.standard,&dialect.subset]{b.repeated(text.len(),16)?}b.finish()}
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;if dialect.artifact_kind!="s.flow.flow"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("Flow dialect differs from its owned wildcard").into())}if d.table("flow_document")?.single_row()?.text(1)?!=self.schema{return Err(String::from("Flow projected schema differs").into())}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(store::io_schema::IoOutcome::clean(()))}
}
